def all_cu_cells_status_should_be_normal(conn_alias='default'):
    """
    checking all of the cells under one vcu should be onair.

    :param str conn_alias: rest api connection alias, default value is 'default'.
    :return: None
    """
    cells_info = vcu_ope_base.get_all_vcu_cells_statuses(conn_alias=conn_alias)
    for cell in cells_info:
        if cell['administrative_state'] != 'Unlocked':
            raise AssertionError('The admin state of NRCELL-{cell_id} is {admin_state}'.format(cell_id=cell['id'],
                                                                                               admin_state=cell[
                                                                                                   'administrative_state']))
        if cell['operational_state'] != 'enabled':
            raise AssertionError(
                'The operational state of NRCELL-{} is {}'.format(cell['id'], cell['operational_state']))

    logger.info('All of the cells statuses are normal.')


def get_all_vcu_cells_statuses(conn_alias='default'):
    """
    Get all vcu cells information

    :param str conn_alias: rest api connection alias, default value is 'default'.
    :return: cells information, return type is dictionary
    """
    cells_info = vcu_ope_base.get_all_vcu_cells_statuses(conn_alias=conn_alias)
    logger.info('End of get_all_vcu_cells_statuses().')
    return cells_info


def all_dus_status_should_be_normal(conn_alias='default'):
    """
    Checking all of the DU should be in normal status.

    :param str conn_alias: rest api connection alias, default value is 'default'.
    :return: None
    """
    dus_summary = vcu_ope_base.get_all_dus_summary_statuses(conn_alias=conn_alias)
    if dus_summary['administrative_state']['locked'] != 0 or dus_summary['f1_link_status']['unavailable'] != 0:
        raise AssertionError('DU status is abnormal')
    logger.info('{} All of the DUs are in normal status {}'.format(LOG_HEAD, LOG_END))


def all_ng_links_active(conn_alias='default'):
    """
    Checking all the NG link status should be active.

    :param str conn_alias: rest api connection alias, default value is 'default'.
    :return: None
    """
    amfs_info = vcu_ope_base.get_cu_amfs_info_from_wbem(conn_alias=conn_alias)
    logger.info('{} All AMFs information are as below\n{}'.format(LOG_HEAD, amfs_info))
    for amf in amfs_info:
        if ams['ng_link_status'] != 'Active':
            raise AssertionError('The status of {} is {}, not active'.format(amf['name'], amf['ng_link_status']))
    logger.info('{} All of NG link statuses are active {}'.format(LOG_HEAD, LOG_END))


def get_vcu_mrbts_name_by_restapi(conn_alias='default'):
    return vcu_ope_base.get_cu_mrbts_id_from_webem(conn_alias=conn_alias)


def get_vcu_sw_release(conn_alias='default'):
    sw_version = vcu_ope_base.get_cu_sw_version_from_webem(conn_alias=conn_alias)
    # "vDUCNF23R2_0.300.946119"
    release = re.search("\\S*(\\d{2}R\\d{1})", sw_version).group(1)
    return release


def get_vcu_sw_stream(conn_alias='default'):
    sw_version = vcu_ope_base.get_cu_sw_version_from_webem(conn_alias=conn_alias)
    # "vDUCNF23R2_0.300.946119"
    stream = re.search("\\d\\d\\w\\d", sw_version).group(0)
    # release = re.search("\\S*(\\d{2}R\\d{1})", sw_version).group(1)
    return stream


def get_vcu_vnfcs_states(conn_alias='default'):
    return vcu_ope_base.get_vnfcs_states_from_webem(conn_alias=conn_alias)


def get_vcu_pod_vnfc_state(pod_abbr, conn_alias='default'):
    pods_state_list = vcu_ope_base.get_vnfcs_states_from_webem(conn_alias=conn_alias)
    pods_state_list_filtered = []
    for pod_state in pods_state_list:
        if pod_abbr in pod_state["name"]:
            pods_state_list_filtered.append(pod_state)
    logger.info('{} {} {} pod are found {}'.format(LOG_HEAD, len(pods_state_list_filtered), pod_abbr, LOG_END))
    return pods_state_list_filtered


def get_vcu_active_pod_name(pod_abbr, conn_alias='default'):
    pod_name = ''
    pod_abbr = '-' + pod_abbr + '-'
    pods_state_list = vcu_ope_base.get_vnfcs_states_from_webem(conn_alias=conn_alias)
    for pod_state in pods_state_list:
        if pod_abbr in pod_state["name"] and pod_state["role"] == "active":
            pod_name = pod_state["name"]
            tmp = pod_name.split('-')
            pod_name = tmp[-2] + '-' + tmp[-1]
    return pod_name


def given_ng_links_status_should_be_as_expected(ng_links_ids=None, expected_ng_link_status='Active',
                                                expected_administrative_state='Unlocked', conn_alias='default'):
    """
    This keyword is used to check the status of given NG links as expected.

    :param list ng_links_ids: a list of NG links id, default value is None which means all of the NG links status should be as expected.
    :param str expected_ng_link_status: expected ng link status, can be 'Active' or 'Inactive', default is 'Active'.
    :param str expected_administrative_state: expected administrative state, can be 'Locked' or 'Unlocked', default is 'Unlocked'.
    :param str conn_alias:  Rest connection alias, default value is 'default'.
    :return: None
    """
    ng_links_info = vcu_ope_base.cu.get_ng_links_info(connection=conn_alias)
    unexpected_ng_links = []
    if ng_links_ids is None:
        for ng_link in ng_links_info:
            try:
                assert ng_link['ng_link_status'] == expected_ng_link_status
                assert ng_link['administrative_state'] == expected_administrative_state
            except AssertionError:
                unexpected_ng_links.append({'ng_link_id': ng_link['served_amf_id'], 'ng_link_status': ng_link['ng_link_status'],
                                            'administrative_state': ng_link['administrative_state']})
    else:
        for ng_link in ng_links_info:
            ng_link_id = ng_link['served_amf_id']
            if ng_link_id in ng_links_ids:
                try:
                    assert ng_link['ng_link_status'] == expected_ng_link_status
                    assert ng_link['administrative_state'] == expected_administrative_state
                except AssertionError:
                    unexpected_ng_links.append({'ng_link_id': ng_link_id, 'ng_link_status': ng_link['ng_link_status'],
                                                'administrative_state': ng_link['administrative_state']})
    if unexpected_ng_links:
        raise AssertionError('The following nglink status is not as expected {}'.format(unexpected_ng_links))


