def given_x2_links_status_should_be_as_expected(x2_links_ids=None, expected_x2_link_status='available',
                                                expected_x2_link_lock='unlocked', conn_alias='default'):
    """
    This keyword is used to check the status of given X2 links as expected.

    :param list x2_links_ids: a list of X2 links id, default value is None which means all of the X2 links status should be as expected.
    :param str expected_x2_link_status: expected X2 link status, can be 'available' or 'unavailable', default is 'available'
    :param str expected_x2_link_lock: expected X2 link lock status, can be 'locked' or 'unlocked', default is 'unlocked'
    :param str conn_alias: Rest connection alias, default value is 'default'.
    :return: None
    """
    x2_links_info = vcu_ope_base.cu.get_x2_links_info(connection=conn_alias)['created']
    unexpected_x2_links_status = []
    if x2_links_ids is None:
        for x2_link in x2_links_info:
            try:
                assert x2_link['x2_link_status'] == expected_x2_link_status
                assert x2_link['x2_link_lock'] == expected_x2_link_lock
            except AssertionError:
                unexpected_x2_links_status.append(
                    {'x2_link_id': x2_link['id'], 'x2_link_status': x2_link['x2_link_status'],
                     'x2_link_lock': x2_link['x2_link_lock']})
    else:
        for x2_link in x2_links_info:
            x2_link_id = x2_link['id']
            if x2_link_id in x2_links_ids:
                try:
                    assert x2_link['x2_link_status'] == expected_x2_link_status
                    assert x2_link['x2_link_lock'] == expected_x2_link_lock
                except AssertionError:
                    unexpected_x2_links_status.append(
                        {'x2_link_id': x2_link_id, 'x2_link_status': x2_link['x2_link_status'],
                         'x2_link_lock': x2_link['x2_link_lock']})
    if unexpected_x2_links_status:
        raise AssertionError('The following x2link status is not as expected {}'.format(unexpected_x2_links_status))


def lock_x2_links_on_vcu(x2_links_ids=None, conn_alias='default'):
    """
    This keyword is used to lock the given X2 links.

    :param list x2_links_ids: a list of X2 links id, default value is None which means all of the X2 links will be locked.
    :param str conn_alias: Rest connection alias, default value is 'default'.
    :return: None
    """
    if x2_links_ids is None:
        x2_links_ids = get_x2_links_ids(conn_alias='default')
    return vcu_ope_base.cu.lock_x2_links(link_ids=x2_links_ids, connection=conn_alias)


def unlock_x2_links_on_vcu(x2_links_ids=None, conn_alias='default'):
    """
    This keyword is used to unlock the given X2 links.

    :param list x2_links_ids: a list of X2 links id, default value is None which means all of the X2 links will be unlocked.
    :param str conn_alias: Rest connection alias, default value is 'default'.
    :return: None
    """
    if x2_links_ids is None:
        x2_links_ids = get_x2_links_ids(conn_alias='default')
    return vcu_ope_base.cu.unlock_x2_links(link_ids=x2_links_ids, connection=conn_alias)


def get_x2_links_ids(conn_alias='default'):
    x2_links_ids = []
    x2_links_info = vcu_ope_base.cu.get_x2_links_info(connection=conn_alias)['created']
    for x2_link in x2_links_info:
        x2_links_ids.append(x2_link['id'])
    return x2_links_ids


def get_ng_links_ids(conn_alias='default'):
    ng_links_ids = []
    ng_links_info = vcu_ope_base.cu.get_ng_links_info(connection=conn_alias)
    for ng_link in ng_links_info:
        ng_links_ids.append(ng_link['served_amf_id'])
    return ng_links_ids


def lock_cell_on_vcu(cell_id_list, conn_alias='default'):
    return vcu_ope_base.cu.lock_cells(cell_ids=cell_id_list, connection=conn_alias)['id']


def lock_cell_on_vcu_should_be_success(operation_id, conn_alias='default'):
    start_time = end_time = time.time()
    while end_time - start_time < 60:
        info = vcu_ope_base.cu.get_operation_state_of_locking_cells(operation_id=operation_id, connection=conn_alias)
        if info['status'] == 'success':
            return
        elif info['status'] == 'ongoing':
            time.sleep(3)
            end_time = time.time()
        else:
            raise Exception('lock cell failed, error info is %s' % info)


def unlock_cell_on_vcu(cell_id_list, conn_alias='default'):
    return vcu_ope_base.cu.unlock_cells(cell_ids=cell_id_list, connection=conn_alias)['id']


def unlock_cell_on_vcu_should_be_success(operation_id, conn_alias='default'):
    start_time = end_time = time.time()
    while end_time - start_time < 60:
        info = vcu_ope_base.cu.get_operation_state_of_unlocking_cells(operation_id=operation_id, connection=conn_alias)
        if info['status'] == 'success':
            return
        elif info['status'] == 'ongoing':
            time.sleep(3)
            end_time = time.time()
        else:
            raise Exception('unlock cell failed, error info is %s' % info)
